     1	// A tiny todo list with due dates, priorities and JSON persistence.
     2	import { readFileSync, writeFileSync } from "node:fs";
     3	
     4	export const PRIORITIES = ["low", "normal", "high"];
     5	
     6	function parseDue(due) {
     7	  if (due === undefined || due === null) return null;
     8	  const d = due instanceof Date ? due : new Date(due);
     9	  if (Number.isNaN(d.getTime())) throw new Error("invalid due date");
    10	  return d.toISOString();
    11	}
    12	
    13	export class TodoList {
    14	  constructor() { this.items = []; this.nextId = 1; }
    15	
    16	  add(title, { due, priority = "normal" } = {}) {
    17	    if (!title) throw new Error("title is required");
    18	    if (!PRIORITIES.includes(priority)) throw new Error(`invalid priority: ${priority}`);
    19	    const item = { id: this.nextId++, title, done: false, due: parseDue(due), priority };
    20	    this.items.push(item);
    21	    return item;
    22	  }
    23	
    24	  complete(id) {
    25	    const item = this.items.find(i => i.id === id);
    26	    if (!item) throw new Error(`item ${id} not found`);
    27	    item.done = true;
    28	    return item;
    29	  }
    30	
    31	  pending() {
    32	    return this.items.filter(i => !i.done);
    33	  }
    34	
    35	  clear() {
    36	    this.items = this.items.filter(i => !i.done);
    37	  }
    38	
    39	  addTag(id, tag) {
    40	    const item = this.items.find(i => i.id === id);
    41	    if (!item) throw new Error(`item ${id} not found`);
    42	    const t = typeof tag === "string" ? tag.trim().toLowerCase() : "";
    43	    if (!t) throw new Error("tag is required");
    44	    if (!item.tags) item.tags = [];
    45	    if (!item.tags.includes(t)) item.tags.push(t);
    46	    return item;
    47	  }
    48	
    49	  removeTag(id, tag) {
    50	    const item = this.items.find(i => i.id === id);
    51	    if (!item) throw new Error(`item ${id} not found`);
    52	    const t = typeof tag === "string" ? tag.trim().toLowerCase() : "";
    53	    item.tags = (item.tags ?? []).filter(x => x !== t);
    54	    return item;
    55	  }
    56	
    57	  byTag(tag) {
    58	    const t = typeof tag === "string" ? tag.trim().toLowerCase() : "";
    59	    return this.items.filter(i => (i.tags ?? []).includes(t));
    60	  }
    61	
    62	  // Case-insensitive; every whitespace-separated term must match the title or a tag.
    63	  search(query) {
    64	    const terms = String(query ?? "").toLowerCase().split(/\s+/).filter(Boolean);
    65	    if (terms.length === 0) return [];
    66	    return this.items.filter(i => {
    67	      const text = [i.title, ...(i.tags ?? [])].join(" ").toLowerCase();
    68	      return terms.every(w => text.includes(w));
    69	    });
    70	  }
    71	
    72	  // Overdue first, then priority (high to low), then due date (none last), then id.
    73	  sorted(now = new Date()) {
    74	    const t = new Date(now).getTime();
    75	    const overdue = i => !i.done && i.due !== null && new Date(i.due).getTime() < t;
    76	    const dueTime = i => (i.due === null ? Infinity : new Date(i.due).getTime());
    77	    return [...this.items].sort((a, b) =>
    78	      overdue(b) - overdue(a) ||
    79	      PRIORITIES.indexOf(b.priority) - PRIORITIES.indexOf(a.priority) ||
    80	      (dueTime(a) === dueTime(b) ? 0 : dueTime(a) < dueTime(b) ? -1 : 1) ||
    81	      a.id - b.id);
    82	  }
    83	
    84	  save(path) {
    85	    writeFileSync(path, JSON.stringify({ nextId: this.nextId, items: this.items }, null, 2));
    86	  }
    87	
    88	  static load(path) {
    89	    const data = JSON.parse(readFileSync(path, "utf8"));
    90	    const list = new TodoList();
    91	    list.items = data.items.map(i => ({
    92	      done: false, due: null, priority: "normal", ...i,
    93	    }));
    94	    list.nextId = Math.max(data.nextId ?? 1, ...list.items.map(i => i.id + 1));
    95	    return list;
    96	  }
    97	}
    98	
    99	// --- Recurring todos (added as separate functions; existing API untouched) ---
   100	export const RECURRENCES = ["daily", "weekly", "monthly"];
   101	
   102	// Next due date (ISO string) after `due` for a recurrence. Monthly dates are
   103	// clamped to the month's last day; `day` is the anchor day-of-month so that
   104	// Jan 31 -> Feb 28 -> Mar 31 rather than drifting to the 28th.
   105	export function nextDue(due, repeat, day) {
   106	  if (!RECURRENCES.includes(repeat)) throw new Error(`invalid recurrence: ${repeat}`);
   107	  const d = new Date(due);
   108	  if (Number.isNaN(d.getTime())) throw new Error("invalid due date");
   109	  if (repeat === "daily") d.setUTCDate(d.getUTCDate() + 1);
   110	  else if (repeat === "weekly") d.setUTCDate(d.getUTCDate() + 7);
   111	  else {
   112	    const anchor = day ?? d.getUTCDate();
   113	    d.setUTCDate(1);
   114	    d.setUTCMonth(d.getUTCMonth() + 1);
   115	    const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
   116	    d.setUTCDate(Math.min(anchor, last));
   117	  }
   118	  return d.toISOString();
   119	}
   120	
   121	// Add a recurring todo. `repeat` is one of RECURRENCES; `due` defaults to now.
   122	TodoList.prototype.addRecurring = function (title, repeat, { due = new Date(), priority } = {}) {
   123	  if (!RECURRENCES.includes(repeat)) throw new Error(`invalid recurrence: ${repeat}`);
   124	  const item = this.add(title, { due, priority });
   125	  item.repeat = repeat;
   126	  item.repeatDay = new Date(item.due).getUTCDate();
   127	  return item;
   128	};
   129	
   130	// Complete an item; if it recurs, schedule the next occurrence.
   131	// Returns { item, next } where next is null for non-recurring items.
   132	TodoList.prototype.completeAndReschedule = function (id) {
   133	  const found = this.items.find(i => i.id === id);
   134	  if (!found) throw new Error(`item ${id} not found`);
   135	  const wasDone = found.done;
   136	  const item = this.complete(id);
   137	  if (wasDone || !item.repeat) return { item, next: null };
   138	  const next = this.add(item.title, { due: nextDue(item.due, item.repeat, item.repeatDay), priority: item.priority });
   139	  next.repeat = item.repeat;
   140	  next.repeatDay = item.repeatDay;
   141	  return { item, next };
   142	};
   143	#!/usr/bin/env node
   144	// Usage: todo add <title> [--due DATE] [--priority low|normal|high]
   145	//        todo done <id>
   146	//        todo list [--tag TAG]
   147	//        todo search <query>
   148	//        todo tag <id> <tag> | untag <id> <tag>
   149	//        todo recur <id> <daily|weekly|monthly|none>
   150	//        todo export --json | --csv
   151	// The list is stored in $TODO_FILE (default: ./todo.json).
   152	import { existsSync } from "node:fs";
   153	import { TodoList } from "../src/todo.js";
   154	
   155	const file = process.env.TODO_FILE ?? "todo.json";
   156	const [cmd, ...args] = process.argv.slice(2);
   157	
   158	function fail(msg) {
   159	  console.error(msg);
   160	  process.exit(1);
   161	}
   162	
   163	function printItems(items) {
   164	  for (const i of items) {
   165	    const due = i.due ? ` (due ${i.due.slice(0, 10)})` : "";
   166	    const tags = i.tags?.length ? ` #${i.tags.join(" #")}` : "";
   167	    const repeat = i.repeat ? ` (${i.repeat})` : "";
   168	    console.log(`${i.id} [${i.done ? "x" : " "}] ${i.priority} ${i.title}${due}${repeat}${tags}`);
   169	  }
   170	}
   171	
   172	function csvField(v) {
   173	  const s = v === null || v === undefined ? "" : Array.isArray(v) ? v.join(";")
   174	    : typeof v === "object" ? JSON.stringify(v) : String(v);
   175	  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
   176	}
   177	
   178	function toCsv(items) {
   179	  const cols = ["id", "title", "done", "due", "priority", "tags", "repeat"];
   180	  return [cols.join(","), ...items.map(i => cols.map(c => csvField(i[c])).join(","))].join("\n");
   181	}
   182	
   183	const list = existsSync(file) ? TodoList.load(file) : new TodoList();
   184	
   185	try {
   186	  if (cmd === "add") {
   187	    const opts = {};
   188	    const words = [];
   189	    for (let i = 0; i < args.length; i++) {
   190	      if (args[i] === "--due") opts.due = args[++i];
   191	      else if (args[i] === "--priority") opts.priority = args[++i];
   192	      else words.push(args[i]);
   193	    }
   194	    const item = list.add(words.join(" "), opts);
   195	    list.save(file);
   196	    console.log(`added ${item.id}: ${item.title}`);
   197	  } else if (cmd === "done") {
   198	    const { item, next } = list.completeAndReschedule(Number(args[0]));
   199	    list.save(file);
   200	    console.log(`completed ${item.id}: ${item.title}`);
   201	    if (next) console.log(`next ${next.id}: due ${next.due.slice(0, 10)}`);
   202	  } else if (cmd === "list") {
   203	    let items = list.sorted();
   204	    const t = args.indexOf("--tag");
   205	    if (t !== -1) {
   206	      if (!args[t + 1]) fail("--tag requires a value");
   207	      const tagged = new Set(list.byTag(args[t + 1]));
   208	      items = items.filter(i => tagged.has(i));
   209	    }
   210	    printItems(items);
   211	  } else if (cmd === "search") {
   212	    if (!args.length) fail("search requires a query");
   213	    printItems(list.search(args.join(" ")));
   214	  } else if (cmd === "tag" || cmd === "untag") {
   215	    if (!args[1]) fail(`usage: todo ${cmd} <id> <tag>`);
   216	    const id = Number(args[0]);
   217	    if (cmd === "tag") list.addTag(id, args[1]);
   218	    else list.removeTag(id, args[1]);
   219	    list.save(file);
   220	    console.log(`${cmd === "tag" ? "tagged" : "untagged"} ${id}: ${args[1]}`);
   221	  } else if (cmd === "recur") {
   222	    const freq = args[1];
   223	    if (!["daily", "weekly", "monthly", "none"].includes(freq)) {
   224	      fail("usage: todo recur <id> <daily|weekly|monthly|none>");
   225	    }
   226	    const item = list.items.find(i => i.id === Number(args[0]));
   227	    if (!item) fail(`item ${args[0]} not found`);
   228	    if (freq === "none") {
   229	      delete item.repeat;
   230	      delete item.repeatDay;
   231	    } else {
   232	      if (!item.due) fail(`item ${item.id} needs a due date to recur`);
   233	      item.repeat = freq;
   234	      item.repeatDay = new Date(item.due).getUTCDate();
   235	    }
   236	    list.save(file);
   237	    console.log(`recurrence for ${args[0]}: ${freq}`);
   238	  } else if (cmd === "export") {
   239	    if (args.includes("--json")) console.log(JSON.stringify(list.items, null, 2));
   240	    else if (args.includes("--csv")) console.log(toCsv(list.items));
   241	    else fail("usage: todo export --json | --csv");
   242	  } else {
   243	    fail("usage: todo add <title> [--due DATE] [--priority P] | done <id> | list [--tag T] | search <q> | tag | untag | recur | export");
   244	  }
   245	} catch (e) {
   246	  fail(e.message);
   247	}
