10	  const env = { ...process.env, TODO_FILE: join(dir, "t.json") };
11	  const run = (...args) => execFileSync("node", ["bin/todo.js", ...args], { env, encoding: "utf8", stdio: "pipe" });
12	  const lines = out => out.trim().split(/\r?\n/).filter(Boolean);
13	  return { run, lines, cleanup: () => rmSync(dir, { recursive: true }) };
